{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE appldatabase.maplemonk.alphanso_FACEBOOK_CONSOLIDATED AS SELECT Adset_Name ,Adset_ID ,FB.ad_id ,FB.ad_name ,\'FACEBOOK\' AS Account_Name ,Account_ID ,Campaign_Name ,Campaign_ID ,CAST(Fb.date_start AS DATE) Date ,SUM(CLICKS) Clicks ,SUM(IFNULL(inline_link_clicks,0)) Link_Clicks ,SUM(SPEND) Spend ,SUM(IMPRESSIONS) Impressions ,SUM(IFNULL(Fc.Conversions,0)) Conversions ,SUM(IFNULL(Fcv.Conversion_Value,0)) Conversion_Value ,SUM(IFNULL(fd.add_to_carts,0)) Add_to_carts ,SUM(IFNULL(fdv.add_to_cart_value,0)) Add_to_cart_value ,SUM(IFNULL(fe.landing_page_views,0)) Landing_page_views ,SUM(IFNULL(ff.initiate_checkouts,0)) Initiate_checkouts ,SUM(IFNULL(ffv.initiate_checkouts_value,0)) Initiate_checkouts_value ,\'FACEBOOK\' Channel ,\'FACEBOOK\' Account FROM appldatabase.maplemonk.alphanso_facebook_customcampaigns_data FB LEFT JOIN ( SELECT ad_id ,ad_name ,date_start ,SUM(CAST(C.value:value::STRING AS FLOAT)) Conversions FROM appldatabase.maplemonk.alphanso_facebook_customcampaigns_data, LATERAL FLATTEN(input => ACTIONS) C WHERE C.value:action_type::STRING = \'offsite_conversion.fb_pixel_purchase\' GROUP BY ad_id, ad_name, date_start HAVING SUM(CAST(C.value:value::STRING AS FLOAT)) IS NOT NULL ) Fc ON Fb.ad_id = Fc.ad_id AND Fb.date_start = Fc.date_start LEFT JOIN ( SELECT ad_id ,ad_name ,date_start ,SUM(CAST(CV.value:value::STRING AS FLOAT)) Conversion_Value FROM appldatabase.maplemonk.alphanso_facebook_customcampaigns_data, LATERAL FLATTEN(input => ACTION_VALUES) CV WHERE CV.value:action_type::STRING = \'offsite_conversion.fb_pixel_purchase\' GROUP BY ad_id, ad_name, date_start HAVING SUM(CAST(CV.value:value::STRING AS FLOAT)) IS NOT NULL ) Fcv ON Fb.ad_id = Fcv.ad_id AND Fb.date_start = Fcv.date_start LEFT JOIN ( SELECT ad_id ,date_start ,SUM(CAST(C.value:value::STRING AS FLOAT)) add_to_carts FROM appldatabase.maplemonk.alphanso_facebook_customcampaigns_data, LATERAL FLATTEN(input => ACTIONS) C WHERE C.value:action_type::STRING = \'offsite_conversion.fb_pixel_add_to_cart\' GROUP BY ad_id, date_start HAVING SUM(CAST(C.value:value::STRING AS FLOAT)) IS NOT NULL ) Fd ON Fb.ad_id = Fd.ad_id AND Fb.date_start = Fd.date_start LEFT JOIN ( SELECT ad_id ,date_start ,SUM(CAST(CV.value:value::STRING AS FLOAT)) Add_to_cart_Value FROM appldatabase.maplemonk.alphanso_facebook_customcampaigns_data, LATERAL FLATTEN(input => ACTION_VALUES) CV WHERE CV.value:action_type::STRING = \'offsite_conversion.fb_pixel_add_to_cart\' GROUP BY ad_id, date_start HAVING SUM(CAST(CV.value:value::STRING AS FLOAT)) IS NOT NULL ) Fdv ON Fb.ad_id = Fdv.ad_id AND Fb.date_start = Fdv.date_start LEFT JOIN ( SELECT ad_id ,date_start ,SUM(CAST(C.value:value::STRING AS FLOAT)) Landing_page_views FROM appldatabase.maplemonk.alphanso_facebook_customcampaigns_data, LATERAL FLATTEN(input => ACTIONS) C WHERE C.value:action_type::STRING = \'landing_page_view\' GROUP BY ad_id, date_start HAVING SUM(CAST(C.value:value::STRING AS FLOAT)) IS NOT NULL ) Fe ON Fb.ad_id = Fe.ad_id AND Fb.date_start = Fe.date_start LEFT JOIN ( SELECT ad_id ,date_start ,SUM(CAST(C.value:value::STRING AS FLOAT)) Initiate_checkouts FROM appldatabase.maplemonk.alphanso_facebook_customcampaigns_data, LATERAL FLATTEN(input => ACTIONS) C WHERE C.value:action_type::STRING = \'offsite_conversion.fb_pixel_initiate_checkout\' GROUP BY ad_id, date_start HAVING SUM(CAST(C.value:value::STRING AS FLOAT)) IS NOT NULL ) Ff ON Fb.ad_id = Ff.ad_id AND Fb.date_start = Ff.date_start LEFT JOIN ( SELECT ad_id ,date_start ,SUM(CAST(CV.value:value::STRING AS FLOAT)) Initiate_checkouts_Value FROM appldatabase.maplemonk.alphanso_facebook_customcampaigns_data, LATERAL FLATTEN(input => ACTION_VALUES) CV WHERE CV.value:action_type::STRING = \'offsite_conversion.fb_pixel_initiate_checkout\' GROUP BY ad_id, date_start HAVING SUM(CAST(CV.value:value::STRING AS FLOAT)) IS NOT NULL ) Ffv ON Fb.ad_id = Ffv.ad_id AND Fb.date_start = Ffv.date_start GROUP BY Adset_Name, Adset_ID, fb.ad_id, fb.AD_NAME, Account_Name, Account_ID, Campaign_Name, Campaign_ID, Fb.date_start ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

